use crate::*;
use semio_framework_value_ordered::OrderedSet;
fn debit(bank:&mut RetainedCloneGrant,fuel:&mut u64,p:RetainedCloneProgress,work:u64){assert!(p.fits(*bank));assert!(work<=*fuel);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;*fuel=fuel.checked_sub(work).unwrap();}
fn close<T:RetireOwned>(value:T,bank:&mut RetainedCloneGrant,fuel:&mut u64,maximum:u64){let mut retirement_actual=None;let mut retirement_work=0;let mut owner=crate::retirement::controlled::ControlledRetirement::new(value).map_err(|(e,_)|e).unwrap();for _ in 0..maximum{if owner.terminal_is_empty()&&retirement_actual.is_none(){break}assert!(owner.next_computational_work(bank.maximum_copy_bytes).unwrap()<=*fuel);let(result,heap)=crate::observe_retirement_allocations(||{let turn=crate::source_fixture::close_step(&mut retirement_actual,RetainedCloneGrant{maximum_items:1,..*bank},*fuel,owner.next_demand(4096),owner.next_computational_work(4096),|g,a|{let result=owner.step(g,a);crate::RetainedWorkOutcome{result,work:owner.last_turn_work()}});retirement_work=turn.work;turn.result});let work=retirement_work;let p=match&result{Ok(step)=>step.progress(),Err(e)=>e.retained_progress()};assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(bank,fuel,p,work);result.unwrap();}assert!(owner.terminal_is_empty());}
#[test]fn actual_native_set_replaces_synchronous_controlled_decode_with_original_staged_custody(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let maximum=s["maximumTurns"].as_u64().unwrap();let expected:std::collections::BTreeSet<String>=serde_json::from_value(law["members"].clone()).unwrap();assert_eq!(serde_json::to_value(&expected).unwrap(),law["expected"]);let input=crate::DslValue::from(&law["members"]);let source={let mut wallet=(&mut bank,&mut fuel);crate::source_fixture::capture(input,&mut wallet,|w|RetainedCloneGrant{maximum_items:w.0.maximum_items.min(1),..*w.0},|w|*w.1,|w,p,work,_,_|debit(w.0,w.1,p,work))};let mut receiver=<OrderedSet as NativeReceive<crate::DslValue>>::receiver();let mut callback=|_|true;let mut control=NativeDecodeControl::new(bank.maximum_capacity_bytes,&mut callback);let mut refused=false;for _ in 0..maximum{if receiver.output_ready(){break}let input=source.borrow();let d=receiver.demands(input,4096,fuel).unwrap();for grant in [Some(RetainedCloneGrant{maximum_items:0,..bank}),(d.copy_bytes>0).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..bank}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..bank}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..bank}),(d.depth>0).then(||RetainedCloneGrant{maximum_depth:d.depth-1,..bank})].into_iter().flatten(){let(turn,heap)=crate::observe_retirement_allocations(||{let maximum=fuel;let grant=grant;crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(input,control,4096,maximum,grant)})});assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}if d.capacity_bytes>0&&!refused{let((turn,attempts),heap)=crate::observe_retirement_allocations(||semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||{let maximum=fuel;let grant=RetainedCloneGrant{maximum_items:1,..bank};crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(input,control,4096,maximum,grant)})}));assert_eq!(attempts,1);assert_eq!(heap,(0,0));assert_eq!(turn.work,1);let work=turn.work;let error=turn.result.unwrap_err();let p=error.retained_progress();assert_eq!(p,Default::default());debit(&mut bank,&mut fuel,p,work);refused=true;continue}let(turn,heap)=crate::observe_retirement_allocations(||{let maximum=fuel;let grant=RetainedCloneGrant{maximum_items:1,..bank};crate::source_fixture::receive(&mut control,grant,crate::source_fixture::WorkLoan::new(&maximum,maximum),|control|{let maximum=control.available_work_units().unwrap();receiver.advance(input,control,4096,maximum,grant)})});let work=turn.work;let step=turn.result.unwrap();if !receiver.output_ready(){assert!(!matches!(step,RetainedCloneStep::Complete(_)));}let p=step.progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,work);}assert!(receiver.output_ready());let turn=receiver.take(RetainedCloneGrant{maximum_items:1,..bank});let work=turn.work;let(output,p)=turn.result.unwrap().unwrap();debit(&mut bank,&mut fuel,p,work);let actual:std::collections::BTreeSet<String>=output.iter().cloned().collect();assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(expected).unwrap());let g=RetainedCloneGrant{maximum_items:1,..bank};let q=receiver.begin_close_work_demand().unwrap();assert!(q<=fuel);let(t,h)=crate::observe_retirement_allocations(||receiver.begin_close_step(g,q));let p=t.result.unwrap().progress();assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,t.work);let mut actual=None;for _ in 0..maximum{if receiver.terminal_is_empty()&&actual.is_none(){break}let(turn,heap)=crate::observe_retirement_allocations(||crate::source_fixture::close_step(&mut actual,RetainedCloneGrant{maximum_items:1,..bank},fuel,receiver.close_demands(4096),receiver.close_work_demand(4096),|g,a|receiver.close_step(g,a)));let work=turn.work;let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,work);}assert!(receiver.terminal_is_empty());drop(receiver);close(output,&mut bank,&mut fuel,maximum);close(source,&mut bank,&mut fuel,maximum);}
